// backend/tests/smsPipelineCore.test.js
//
// Plain-English what this checks: the main backend runs the SMS reader's OWN decisions (backend/smsPipelineCore.js, a word-for-word
// copy of sms-parser-backend/Code.js generated by tools/build_sms_pipeline.py). This proves (1) the copy is up to date, and (2) the old
// SMS reader and the copy give IDENTICAL answers (is it a transaction / why ignored / every parsed detail) for every message we have:
// a built-in list of tricky examples always, and, if this computer has it, every real message the phone ever received
// (local-data/sms_corpus.json, never committed). (3) the duplicate rules give identical answers against the same past rows.
// Run with: node backend/tests/smsPipelineCore.test.js

const fs = require("fs");
const path = require("path");
const vm = require("vm");
const { build } = require("./_ownerWorld");
const { assert } = require("./_fakeSheetsKit");

const ROOT = path.join(__dirname, "..", "..");
const CODE = path.join(ROOT, "sms-parser-backend", "Code.js");

console.log("\n--- 1. The copy is up to date ---");
{
  const text = fs.readFileSync(CODE, "utf8").replace(/\r\n/g, "\n");
  const begin = "// ==== SMS-PIPELINE-CORE-BEGIN ====", end = "// ==== SMS-PIPELINE-CORE-END ====";
  let b = text.indexOf(begin); b = text.indexOf("\n", text.indexOf("\n", b) + 1) + 1;
  const core = text.slice(b, text.indexOf(end)).replace(/\s+$/, "") + "\n";
  const generated = fs.readFileSync(path.join(ROOT, "backend", "smsPipelineCore.js"), "utf8").replace(/\r\n/g, "\n");
  assert(generated.indexOf(core) !== -1, "backend/smsPipelineCore.js contains the SMS reader's core exactly (if this fails: run python tools/build_sms_pipeline.py)");
}

// ---- the OLD SMS reader, loaded the way its own tests load it
function loadOld(rows){
  const sandbox = {
    SpreadsheetApp: { openById: function(){ return { getSheetByName: function(){
      return {
        getLastRow: function(){ return rows.length + 1; },
        getRange: function(r, c, nr, nc){ return { getValues: function(){ return rows.map(function(row){ const o = []; for(let i = 0; i < nc; i++) o.push(row[c - 1 + i] !== undefined ? row[c - 1 + i] : ""); return o; }); } }; },
        appendRow: function(){}
      };
    } }; } },
    ContentService: { createTextOutput: function(t){ return { text: t }; } },
    LockService: { getScriptLock: function(){ return { waitLock: function(){}, releaseLock: function(){} }; } },
    Utilities: { formatDate: function(date, tz, fmt){
      const ms = new Date(date).getTime() + 330 * 60000;                      // India time
      const d = new Date(ms); const pad = function(n){ return String(n).padStart(2, "0"); };
      if(fmt === "HH:mm:ss") return pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes()) + ":" + pad(d.getUTCSeconds());
      return d.getUTCFullYear() + "-" + pad(d.getUTCMonth() + 1) + "-" + pad(d.getUTCDate());
    } },
    console: console
  };
  vm.createContext(sandbox);
  vm.runInContext(fs.readFileSync(CODE, "utf8"), sandbox, { filename: "Code.js" });
  return sandbox;
}

// ---- the NEW copy, inside the main backend's world; its "past rows" come from the person's private Transactions tab
const w = build(); const sb = w.sb;
sb.Utilities.formatDate = loadOld([]).Utilities.formatDate;   // the same India-time formatter on both sides, so only the logic is compared
const TXN_HEADER = ["Date", "Time", "Bank", "Type", "Mode", "Amount", "Reference", "Counterparty", "Channel", "Source", "RawSMS", "Sender", "Note", "Category"];
function setRows(rows){
  w.addSheet("Transactions", [TXN_HEADER].concat(rows));
  return rows;
}

const fixed = [
  ["HDFCBK", "Sent Rs.40.00 From HDFC Bank A/C x1234 To Aarogyumm Cafe On 13/10/26 Ref 665226905838 Not You? Call 18002586161"],
  ["HDFCBK", "Rs.1,250.00 debited from A/c XX9876 on 13-10-26 to RAHUL SHARMA (rahul@okhdfc) UPI Ref 628419375012. Bal Rs.8,430.55."],
  ["ICICIB", "ICICI Bank Acct XX123 credited with Rs. 45,000.00 on 05-Sep-26; Info: NEFT-SALARY. Avl Bal Rs 50,000"],
  ["JM-HDFCBK-S", "Mandate Set Rs.15000.00 For Google Cloud From HDFC Bank A/c x8774 UMN: 8f28e1333a32411a823cbb8a70a6ffdc@ok"],
  ["VG-611112-P", "Your favourite Rs.299 plan will stay available on Vi. Recharge today https://vi.example/x"],
  ["AX-AXISBK", "Rs 500 was spent on your Axis Bank Credit Card XX5555 at SWIGGY on 12-10-26. Avl limit Rs 40000"],
  ["BOBSMS", "Rs.100.00 Dr. from A/c XX1111 and Cr. to rahul@upi. Ref:111111111111. AvlBal Rs 500(2026:10:13 12:00:00)-Bank of Baroda"],
  ["XXXX", "hello how are you"],
  ["HDFCBK", "Your OTP is 123456. Do not share it with anyone."],
  ["HDFCBK", "Get a Loan on your HDFC Bank Credit Card @ ZERO Processing Fee https://1.hdfc.bank.in/HDFCBK/s/V6JLK9Rx"],
  ["HDFCBK", "{\"rich\":\"card\",\"text\":\"The full loan amount is credited directly to your bank account\"}"],
  ["HDFCBK", "HDFC Bank Cardmember, Online Payment of Rs.149 vide Ref# 248BRN0JG4RDKDW was credited to your card ending 1264"]
];

console.log("\n--- 2. Old SMS reader and the copy agree on every message ---");
{
  const old = loadOld([]);
  let corpus = fixed.map(function(x){ return { sender: x[0], sms: x[1] }; });
  const real = path.join(ROOT, "local-data", "sms_corpus.json");
  let realCount = 0;
  if(fs.existsSync(real)){ const extra = JSON.parse(fs.readFileSync(real, "utf8")); realCount = extra.length; corpus = corpus.concat(extra); }
  let diffs = 0, shown = 0, counts = { IGNORE: 0, TRANSACTION: 0, UNCERTAIN: 0 };
  corpus.forEach(function(m){
    const a = JSON.stringify(old.classifyDetail(m.sms, m.sender));
    const b = JSON.stringify(sb.SmsPipeline.classifyDetail(m.sms, m.sender));
    let pa = "", pb = "";
    const kind = JSON.parse(a).result; counts[kind] = (counts[kind] || 0) + 1;
    if(kind !== "IGNORE"){ pa = JSON.stringify(old.ruleParser(m.sms, m.sender)); pb = JSON.stringify(sb.SmsPipeline.ruleParser(m.sms, m.sender)); }
    if(a !== b || pa !== pb){ diffs++; if(shown++ < 3) console.error("  DIFF for " + JSON.stringify(m.sms.slice(0, 90)) + "\n    old " + a + pa + "\n    new " + b + pb); }
  });
  assert(diffs === 0, "identical answers for all " + corpus.length + " messages (" + realCount + " real ones from the phone) - transaction " + counts.TRANSACTION + ", uncertain " + counts.UNCERTAIN + ", ignored " + counts.IGNORE);
  assert(counts.TRANSACTION > 5 && counts.IGNORE > 3, "the list really exercises both outcomes");
}

console.log("\n--- 3. The duplicate rules agree against the same past rows ---");
{
  const today = new Date(Date.UTC(2026, 9, 13, 6, 0, 0));
  const ts = Math.floor(today.getTime() / 1000);
  const rows = [
    ["2026-10-13", "11:30:00", "HDFC", "debit", "upi", 40, "665226905838", "aarogyumm cafe", "SMS", "Tasker", "Sent Rs.40.00 From HDFC Bank A/C x1234 To Aarogyumm Cafe On 13/10/26 Ref 665226905838", "HDFCBK"],
    ["2026-10-13", "11:31:00", "HDFC", "debit", "upi", 99, "NOREF_47", "google asia pacific", "Import", "Credit Card Statement", "-", "-"],
    ["2026-10-13", "09:00:00", "HDFC", "debit", "card 8132", 700, "ABC123", "swiggy", "SMS", "Tasker", "Rs 700 spent on card XX8132 at SWIGGY", "HDFCBK"]
  ];
  const old = loadOld(rows);
  setRows(rows);
  const cases = [
    [{ amount: "40", type: "debit", reference: "665226905838", counterparty: "aarogyumm cafe" }, "different words", ts],       // same reference
    [{ amount: "40", type: "debit", reference: "999999999999", counterparty: "aarogyumm cafe" }, rows[0][10], ts],             // same text
    [{ amount: "99", type: "debit", reference: "", counterparty: "google asia pacific pte" }, "Rs.99 UPI google asia pacific", ts],   // placeholder match
    [{ amount: "99", type: "debit", reference: "", counterparty: "" }, "Rs.99 UPI/DR/1234/x", ts],                              // no name: must NOT match
    [{ amount: "12", type: "debit", reference: "111222333444", counterparty: "new shop" }, "Rs.12 debited to new shop", ts],    // brand new
    [{ amount: "700", type: "debit", reference: "", counterparty: "swiggy" }, "Rs.700 without OTP/PIN Card XX8132 SWIGGY", ts]   // card echo shape
  ];
  let same = 0;
  cases.forEach(function(c){
    const a = JSON.stringify(old.isDuplicate(c[0], c[1], c[2])), b = JSON.stringify(sb.SmsPipeline.isDuplicate(c[0], c[1], c[2]));
    if(a === b) same++; else console.error("  DIFF dup: old " + a + " new " + b + " for " + JSON.stringify(c[0]));
  });
  assert(same === cases.length, "all " + cases.length + " duplicate cases give the same answer (same reference, same text, statement placeholder, unnamed, brand new, card echo)");
  assert(sb.SmsPipeline.isDuplicate(cases[0][0], cases[0][1], cases[0][2]).duplicate === true && sb.SmsPipeline.isDuplicate(cases[4][0], cases[4][1], cases[4][2]).duplicate === false, "and they really detect a duplicate and a new message");
}
